name: Dependabot Auto Merge

on:
  pull_request:
    types: [opened, synchronize, reopened]
  workflow_run:
    workflows: ["CI"]
    types: [completed]

jobs:
  dependabot-auto-merge:
    runs-on: ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
      checks: read
      statuses: read
    env:
      PR_NUMBER: ${{ github.event.pull_request.number || github.event.workflow_run.pull_requests[0].number }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Verify Dependabot PR
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = process.env.PR_NUMBER;
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            if (pr.user.login !== 'dependabot[bot]') {
              core.setFailed('This workflow only processes Dependabot PRs.');
            }

      - name: Wait for status propagation
        if: github.event_name == 'workflow_run'
        run: sleep 5

      - name: Validate checks
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = process.env.PR_NUMBER;
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });

            const { data: status } = await github.rest.repos.getCombinedStatusForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: pr.head.sha
            });

            if (!status || !status.statuses || status.statuses.length === 0) {
              core.setFailed('No combined status found for this PR.');
            }

            const hasFailed = status.statuses.some(s => s.state === 'failure' || s.state === 'error');
            const hasCancelled = status.statuses.some(s => s.state === 'cancelled');
            if (hasFailed || hasCancelled) {
              core.setFailed('One or more checks failed or were cancelled.');
            }

            const { data: checkRuns } = await github.rest.checks.listForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: pr.head.sha
            });

            if (!checkRuns || !checkRuns.check_runs || checkRuns.check_runs.length === 0) {
              core.setFailed('No check runs found for this PR.');
            }

            const failedCheck = checkRuns.check_runs.find(cr => cr.conclusion !== 'success' && cr.conclusion !== null);
            if (failedCheck) {
              core.setFailed(`Check run "${failedCheck.name}" failed with conclusion "${failedCheck.conclusion}".`);
            }

      - name: Auto-approve PR
        uses: actions/github-script@v6
        with:
          script: |
            const prNumber = process.env.PR_NUMBER;
            const { data: reviews } = await github.rest.pulls.listReviews({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber
            });
            const hasApproved = reviews.some(r => r.state === 'APPROVED' && r.user.login === context.actor);
            if (!hasApproved) {
              await github.rest.pulls.createReview({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: prNumber,
                event: 'APPROVE',
                body: 'Auto-approved by Dependabot auto-merge workflow.'
              });
            }

      - name: Enable auto-merge
        uses: peter-evans/enable-pull-request-automerge@v3
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          pull-request-number: ${{ env.PR_NUMBER }}
          merge-method: squash
```

